@startuml

class Aircraft {
  + Model : string
  + ConstructionYear : date
  + NextInspection : date
}

class Contract {
  + ContractNumber : int
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionId : int
  + Model : string
  + Price : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

class Salesperson {
  + EmployeeId : int
  + FirstName : string
  + LastName : string
}

class Airline {
  + AirlineId : int
  + Name : string
  + Address : string
  + ParentAirlineId : int?
}

class ContractManagement {
  + ContractNumber : int
  + SalespersonId : int
}

Aircraft "1" -- "0..*" Acquisition
Contract "1" -- "*" Acquisition
Salesperson "1" -- "*" ContractManagement
Airline "1" -- "0..*" Airline

@enduml

